const fs = require("fs");
const { execSync } = require("child_process");
const b = JSON.parse(fs.readFileSync("build.json", "utf8"));
const commit = execSync("git rev-parse --short HEAD", { encoding: "utf8" }).trim();
const stamp = [
  "/* generated by tools/stamp-build-rc107.js — do not hand-edit */",
  `window.PLAY_BUILD = ${JSON.stringify(b.appBuild)};`,
  `window.PLAY_SPRITE_BUILD = ${JSON.stringify(b.spriteBuild)};`,
  `window.PLAY_LOCATION_BUILD = ${JSON.stringify(b.locationBuild)};`,
  `window.PLAY_GIT_COMMIT = ${JSON.stringify(commit)};`,
  `window.PLAY_DEPLOYED_AT = ${JSON.stringify(new Date().toISOString())};`,
  ""
].join("\n");
fs.writeFileSync("js/build.js", stamp);
console.log(stamp);
